{"drafts": [{"draft_id": "54c116ea-b615-59c6-bc4e-ded08ff8f576", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "name": "信号相位进入判定", "description": "根据当前 tick 与信号周期相位，判断某条入边是否处于绿灯，从而决定车辆能否进入目标节点；用于逐 tick 推进仿真时确定车辆通行许可。", "asset_type": "micro_skill", "granularity": "micro", "asset_node_id": "micro_skill_node", "asset_path": "family_root/macro_skill/workflow_skill/micro_skill_node", "asset_level": 3, "visible_role": "leaf", "objective": "在给定 tick 下判定入边绿灯状态并输出车辆可否进入节点", "domain": "交通仿真", "task_family": "逐tick状态推进", "method_family": "信号相位取模判定", "stage": "车辆移动决策", "applicable_signals": ["当前 tick 已知", "信号周期与相位划分已知", "目标入边受信号控制"], "contraindications": ["无信号控制的路口", "非离散时间步仿真"], "intervention_moves": ["计算 t mod 周期长度", "将余数映射到相位", "查该相位下入边绿灯状态", "输出进入许可或等待至下一绿灯相位"], "workflow_steps": ["读取当前 tick 与信号周期长度", "计算 t mod 周期长度得到相位索引", "确定该相位下目标入边的绿灯状态", "若绿灯输出允许进入；否则计算下一绿灯相位对应 tick 并输出等待"], "triggers": ["需要判断某车辆在某 tick 能否进入节点", "存在多相位信号周期", "逐 tick 推进仿真需确定通行许可"], "constraints": ["判定仅基于相位与 tick，不引入容量或事故因素", "相位划分须与信号周期定义一致"], "cautions": ["不同入边在同一相位下绿灯状态可能不同，需逐边判定"], "output_contract": ["输出该 tick 下各入边绿灯状态及车辆进入许可（允许进入或等待至指定 tick）"], "examples": [{"input": "tick 6，周期 6，Phase A 下 E2 绿灯、E5 非绿灯", "output": "E2 允许进入；E5 需等待至 Phase B（tick 8 或 9）", "notes": "t mod 6 = 0 对应 Phase A"}], "risk_class": "low", "confidence": 0.7, "support_ids": ["8ad4daa8-ddd6-5ddc-b4e4-920904b7937c"], "metadata": {"prompt": "给定当前 tick、信号周期长度与相位划分，先计算 t mod 周期，确定当前所处相位；再查该相位下目标入边是否为绿灯；若为绿灯则输出允许进入，否则输出需等待并给出下一个可进入的相位对应 tick。仅做单次相位判定，不处理容量、排队或事故。", "tags": ["交通仿真", "信号相位", "逐tick推进", "通行许可"], "files": {}, "resources": {}, "source_sections": ["User Questions"], "extraction_unit": "window", "domain_type": "traffic simulation rules", "taxonomy_id": "traffic simulation rules", "asset_node_id": "micro_skill_node", "asset_path": "family_root/macro_skill/workflow_skill/micro_skill_node", "asset_level": 3, "visible_role": "leaf", "candidate_slot": 1, "window_id": "0d40d51a-a72b-555d-998b-30fe932e7857", "window_strategy": "